Especificador Tipo Exemplo <code>%d</code> Inteiro <code>%05d</code> → 00042 <code>%f</code> Decimal <code>%.2f</code> → 3.14 <code>%s</code> String <code>%-10s</code> → alinhado à esquerda <code>%n</code> Quebra linha <code>"Linha1%nLinha2"</code> <pre><code>double preco = 19.9876;
System.out.printf("Preço: R$ %,.2f%n", preco); // Preço: R$ 19,99
</code></pre> <pre><code>public class Saida {
    public static void main(String[] args) {
        System.out.print("Olá, ");        // Sem quebra
        System.out.println("Mundo!");     // Com quebra
        System.out.printf("PI: %.2f", Math.PI); // PI: 3.14
    }
}
</code></pre>

Método Tipo Lido <code>nextInt()</code> <code>int</code> <code>nextDouble()</code> <code>double</code> <code>nextLine()</code> <code>String</code> (linha) <code>next().charAt(0)</code> <code>char</code> (primeiro caractere) <pre><code>public class Entrada {
    public static void main(String[] args) {
        Scanner leitor = new Scanner(System.in);

        System.out.print("Nome: ");
        String nome = leitor.nextLine();

        System.out.print("Idade: ");
        int idade = leitor.nextInt();

        System.out.printf("%s tem %d anos.", nome, idade);
        leitor.close(); // Fechar o scanner!
    }
}
</code></pre>
